(() => {
const app = window.__CITY_APP, C = window.CITY, t = C.worldFromLatLon(43.644, -79.3806);
let best = null, bd = 1e9;
for (const tr of app.railCorridor.trains) { if (tr.wait > 0) continue; const c = tr.cars[0]; const d = Math.hypot(c.x - t.x, c.z - t.z); if (d < bd) { bd = d; best = tr; } }
console.log('[shot] train ' + Math.round(bd) + ' m from target, speed ' + best.speed.toFixed(1) + ', ' + app.railCorridor.trains.length + ' trains');
const c0 = best.cars[0]; app.teleportTo(c0.x + 40, c0.z + 40, 0);
app.cameraSystem.cinema = () => { const n = best.cars[0], m = best.cars[3]; const fx = Math.sin(n.yaw), fz = Math.cos(n.yaw), rx = -fz, rz = fx;
return { pos: [n.x + fx * 80 + rx * 0, n.y + 22, n.z + fz * 80 + rz * 0], look: [m.x, m.y + 2.4, m.z], fov: 55 }; };
})()

